const loonSettingsPath = join(process.env.PI_CODING_AGENT_DIR || join(os.homedir(), ".pi", "agent"), "loon-tui.json");
const readLoonSettings = async (): Promise<Record<string, unknown>> => {
	try {
		const parsed: unknown = JSON.parse(await readFile(loonSettingsPath, "utf8"));
