let loonBannerSource: "loon" | "rose" | "off" = loonSettings.source === "rose" || loonSettings.source === "off" ? loonSettings.source : "loon";
const writeLoonSettings = async (next: Record<string, unknown>) => {
	const { mkdir, rename, writeFile } = await import("node:fs/promises");
	await mkdir(dirname(loonSettingsPath), { recursive: true });
	const temporary = `${loonSettingsPath}.${process.pid}.tmp`;
	await writeFile(temporary, `${JSON.stringify(next, null, "\t")}\n`, { mode: 0o600 });
	await rename(temporary, loonSettingsPath);
