    const home = process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");
    const parsed: unknown = JSON.parse(await readFile(join(home, "loon-tui.json"), "utf8"));
    if (typeof parsed !== "object" || parsed === null) return undefined;
